35	function applyInverse(pass: boolean, inverse: boolean) {
36	  return inverse ? !pass : pass;
37	}
38	
39	function formatStepList(stepLabels: string[]): string {
40	  return stepLabels.length > 0 ? stepLabels.join(', ') : '(none)';
41	}
42	
43	function requireNamedTrajectoryMatcher(
44	  matcher: TrajectoryStepMatcher,
45	  assertionType: string,
46	  index?: number,
47	) {
48	  if (matcher.pattern || matcher.name) {
49	    return;
50	  }
51	
52	  const stepLabel = index === undefined ? 'object' : `step ${index + 1}`;
53	  throw new Error(
54	    `${assertionType} assertion ${stepLabel} must include a name or pattern property`,
55	  );
56	}
57	
58	function resolveGoalSuccessValue(value: unknown): TrajectoryGoalSuccessValue {
59	  if (typeof value === 'string' && value.trim()) {
60	    return { goal: value.trim() };
61	  }
62	
63	  if (
64	    value &&
65	    typeof value === 'object' &&
66	    !Array.isArray(value) &&
67	    typeof (value as TrajectoryGoalSuccessValue).goal === 'string' &&
68	    (value as TrajectoryGoalSuccessValue).goal.trim()
69	  ) {
70	    return {
71	      goal: (value as TrajectoryGoalSuccessValue).goal.trim(),
72	    };
73	  }
74	
75	  throw new Error(
76	    'trajectory:goal-success assertion must have a string value or an object with a goal property',
77	  );
78	}
